WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), shipped_date) AS days_since_shipped_date, COALESCE(carrier, 'DIRECT') AS resolved_carrier FROM shipments WHERE status = 'IN_TRANSIT') SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, days_since_shipped_date, resolved_carrier, AVG(cost) OVER (PARTITION BY order_id ORDER BY cost, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS cost_avg_2, SUM(cost) OVER (PARTITION BY carrier) AS carrier_sum_cost, LEAD(cost, 1) OVER (PARTITION BY status, carrier ORDER BY days_since_shipped_date, id) AS next_cost, LAG(cost, 2) OVER (PARTITION BY order_id ORDER BY shipped_date, id) AS prev_cost, ROUND(cost / SUM(cost) OVER (PARTITION BY status), 4) AS cost_share FROM filtered
